import DOMPurify from 'dompurify';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Sanitise HTML authored by teachers or generated by AI before it is put into the page.
 * Strips scripts, event handlers and javascript: URLs so stored content cannot run code
 * in another user's session.
 */
export function sanitizeHtml(html: string | null | undefined): string {
  if (!html) return '';
  return DOMPurify.sanitize(html, { USE_PROFILES: { html: true }, ADD_ATTR: ['target'] });
}

/** Returns the URL only if it is a plain http(s) link; otherwise an empty string. */
export function safeUrl(url: string | null | undefined): string {
  if (!url) return '';
  const trimmed = url.trim();
  return /^https?:\/\//i.test(trimmed) ? trimmed : '';
}
